sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // 1. Room's category must have beds (Operation Theatres cannot have patient beds)
    if (!current.room.nil()) {
        var roomCategory = current.room.room_category.toString();
        if (roomCategory == 'Operation Theatre') {
            gs.addErrorMessage('Beds cannot be assigned to an Operation Theatre. Room category must be a ward, ICU, or patient room.');
            current.setAbortAction(true);
            return;
        }
    }

    // 2. Assignment / Reservation:
    // Bed can be Reserved ('2') from Available ('1')
    // Bed can be Occupied ('3') from Available ('1') or Reserved ('2')
	// Bed state can only move to Under Cleaning('4) from Occupied('3)
    if (current.status.changes()) {
        var newStatus = current.getValue('status');
        var prevStatus = previous ? previous.getValue('status') : '';

        if (newStatus == '2') {
            if (prevStatus && prevStatus != '1') {
                gs.addErrorMessage('A bed can only be reserved from "Available" status. Current status is "' + previous.status.getDisplayValue() + '".');
                current.setAbortAction(true);
                return;
            }
        } else if (newStatus == '3') {
            if (prevStatus && prevStatus != '1' && prevStatus != '2') {
                gs.addErrorMessage('A bed can only be occupied from "Available" or "Reserved" status. Current status is "' + previous.status.getDisplayValue() + '".');
                current.setAbortAction(true);
                return;
            }
        }
		else if (prevStatus == '3') {
            if (newStatus && newStatus !='4') {
                gs.addErrorMessage('A bed can only move to Under Cleaning from Occupied Status.');
                current.setAbortAction(true);
                return;
            }
        }
		else if (prevStatus == '6' || prevStatus == '7') {
            if ((newStatus && newStatus != '4' ) && (newStatus && newStatus !='5')) {
                gs.addErrorMessage('A bed can only move to Under Cleaning or Under Maintenance from Out of Service or Blocked Status.');
                current.setAbortAction(true);
                return;
            }
        }
    }

})(current, previous);
